/**
 * CallBird AI — Custom Templates
 * 
 * Per-business template file. Each template is a full 1080×1350
 * HTML design matching CallBird's brand identity.
 * 
 * Two visual modes:
 *   Dark (#0a1628 navy) — narrative, story, comparison, feature posts
 *   Light (#ffffff white) — stat, data, CTA, urgency posts
 * 
 * Path: src/content-render/callbird-templates.js
 */

const LOGO_B64 = '';

// ── Highlight words in gold ─────────────────────────────────────
function highlightText(text, highlights) {
  if (!text || !highlights?.length) return text || '';
  let result = text;
  highlights.forEach(word => {
    const regex = new RegExp(`(${word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')})`, 'gi');
    result = result.replace(regex, `<span class="hl">$1</span>`);
  });
  return result;
}

// ── Shared CSS ──────────────────────────────────────────────────
function baseCSS(mode = 'dark') {
  const isDark = mode === 'dark';
  return `
    @import url('https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&family=Inter:wght@400;500;600;700&display=swap');
    
    * { margin: 0; padding: 0; box-sizing: border-box; }
    
    .post {
      width: 1080px;
      height: 1350px;
      background: ${isDark ? 'linear-gradient(180deg, #0a1628 0%, #0d1f3c 40%, #0a1628 100%)' : '#ffffff'};
      color: ${isDark ? '#ffffff' : '#1a1a2e'};
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      position: relative;
    }
    
    .hl { color: #F6B828; }
    
    .header {
      padding: 72px 88px 0;
      display: flex;
      align-items: center;
      gap: 18px;
      flex-shrink: 0;
    }

    .header-logo {
      width: 64px;
      height: 64px;
      object-fit: contain;
      background: transparent;
      border: none;
    }

    .header-brand {
      font-family: 'Sora', sans-serif;
      font-size: 30px;
      font-weight: 700;
      color: ${isDark ? '#ffffff' : '#122092'};
      letter-spacing: -0.02em;
    }

    .content {
      flex: 1;
      padding: 56px 88px;
      display: flex;
      flex-direction: column;
      justify-content: flex-start;
    }

    .headline {
      font-family: 'Sora', sans-serif;
      font-weight: 800;
      line-height: 1.05;
      letter-spacing: -0.03em;
      margin-bottom: 24px;
    }

    .subtext {
      font-size: 26px;
      line-height: 1.5;
      color: ${isDark ? 'rgba(255,255,255,0.7)' : '#4a4a6a'};
      margin-bottom: 40px;
      font-weight: 400;
    }

    .footer {
      height: 116px;
      background: transparent;
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 0 88px;
      flex-shrink: 0;
      border-top: 1px solid ${isDark ? 'rgba(255,255,255,0.06)' : 'rgba(18,32,146,0.08)'};
    }

    .footer-tag {
      font-family: 'Sora', sans-serif;
      font-size: 20px;
      font-weight: 600;
      color: ${isDark ? 'rgba(255,255,255,0.7)' : '#4a4a6a'};
      letter-spacing: -0.005em;
    }

    .url-pill {
      background: #F6B828;
      color: #122092;
      font-family: 'Sora', sans-serif;
      font-size: 22px;
      font-weight: 800;
      padding: 16px 32px;
      border-radius: 999px;
      letter-spacing: -0.01em;
    }
  `;
}

// ── Header HTML ─────────────────────────────────────────────────
function headerHTML() {
  return `
    <div class="header">
      <img class="header-logo" src="data:image/png;base64,${LOGO_B64}" alt="CallBird"/>
      <span class="header-brand">CallBird AI</span>
    </div>
  `;
}

// ── Footer HTML ─────────────────────────────────────────────────
// Clean footer: tagline left, gold pill URL right. No eye icon, no counter.
function footerHTML(insightText) {
  const tag = insightText || 'AI receptionist for small business.';
  return `
    <div class="footer">
      <div class="footer-tag">${tag}</div>
      <div class="url-pill">callbirdai.com</div>
    </div>
  `;
}

function wrapHTML(css, body) {
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><style>${css}</style></head><body>${body}</body></html>`;
}


// ═══════════════════════════════════════════════════════════════════
// TEMPLATE: STAT CALLOUT (Light Mode)
// Big stat card at top, bold headline, body, 3 stat pills, footer
// ═══════════════════════════════════════════════════════════════════

function statCallout(content) {
  const statNum = content.headline || content.stat_number || '62%';
  const statLabel = content.subtext || 'of callers won\'t leave a voicemail.';
  const body = content.items?.[0] || content.body_text || '';
  const highlights = content.highlight_words || [];
  
  const items = content.items || ['24/7|Every call answered', '2s|Average pickup', '40%|More booked'];
  const statPills = items.slice(0, 3).map(item => {
    if (typeof item === 'string' && item.includes('|')) {
      const [num, label] = item.split('|');
      return { num, label };
    }
    return { num: '', label: item };
  });

  const css = baseCSS('light') + `
    .stat-card {
      margin: 48px 64px 0;
      background: linear-gradient(135deg, #122092, #1a35b8);
      border-radius: 24px;
      padding: 56px 48px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .stat-card::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -30%;
      width: 300px;
      height: 300px;
      background: rgba(246, 184, 40, 0.1);
      border-radius: 50%;
    }
    .stat-number {
      font-family: 'Sora', sans-serif;
      font-size: 128px;
      font-weight: 800;
      color: #ffffff;
      line-height: 1;
      letter-spacing: -0.04em;
      margin-bottom: 12px;
    }
    .stat-desc {
      font-size: 28px;
      color: rgba(255,255,255,0.85);
      line-height: 1.4;
      max-width: 600px;
      margin: 0 auto;
    }
    .body-section {
      padding: 48px 64px;
      flex: 1;
    }
    .body-headline {
      font-family: 'Sora', sans-serif;
      font-size: 52px;
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      color: #1a1a2e;
      margin-bottom: 24px;
    }
    .body-text {
      font-size: 24px;
      line-height: 1.6;
      color: #4a4a6a;
    }
    .stat-pills {
      display: flex;
      gap: 16px;
      padding: 0 64px;
      margin-bottom: 0;
    }
    .stat-pill {
      flex: 1;
      background: #f0f4ff;
      border: 2px solid #e0e7ff;
      border-radius: 16px;
      padding: 24px 20px;
      text-align: center;
    }
    .pill-num {
      font-family: 'Sora', sans-serif;
      font-size: 40px;
      font-weight: 800;
      color: #122092;
      line-height: 1;
      margin-bottom: 6px;
    }
    .pill-label {
      font-size: 16px;
      color: #6b7280;
      font-weight: 500;
    }
    .mascot-float {
      position: absolute;
      top: 36px;
      right: 64px;
      width: 80px;
      height: 80px;
      object-fit: contain;
    }
  `;

  const secondHeadline = content.cta_line1 || 'Every missed call is revenue walking out your door.';

  const html = `
    <div class="post">
      <img class="mascot-float" src="data:image/png;base64,${LOGO_B64}" alt=""/>
      <div class="stat-card">
        <div class="stat-number">${statNum}</div>
        <div class="stat-desc">${statLabel}</div>
      </div>
      <div class="body-section">
        <div class="body-headline">${highlightText(secondHeadline, highlights)}</div>
        <div class="body-text">${body}</div>
      </div>
      <div class="stat-pills">
        ${statPills.map(p => `
          <div class="stat-pill">
            <div class="pill-num">${p.num}</div>
            <div class="pill-label">${p.label}</div>
          </div>
        `).join('')}
      </div>
      ${footerHTML(content.cta_line2 || 'Stop losing jobs to voicemail')}
    </div>
  `;

  return wrapHTML(css, html);
}


